/* State, selectors and domain helpers shared across pages. This is a frontend simulation. */
(function(root){'use strict';const TF=root.TF;
TF.escape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
TF.id=p=>p+'_'+(root.crypto?.randomUUID?.()||Date.now().toString(36)+Math.random().toString(36).slice(2,8));
TF.clone=obj=>JSON.parse(JSON.stringify(obj));TF.db=TF.makeSeed();TF.persistence=true;
try{const saved=JSON.parse(root.localStorage?.getItem(TF.STORAGE_KEY)||'null');if(saved&&saved.schema===3&&Array.isArray(saved.tasks)&&Array.isArray(saved.projects))TF.db=saved;}catch(e){TF.persistence=false;}
TF.ui={route:'dashboard',search:'',filters:{},tabs:{},modal:null,drawer:null,calendarMode:'month',calendarMonth:9,calendarYear:2026,calendarDay:TF.DEMO_DATE,reportPeriod:'all',reportDept:'All departments',boardProject:'all',projectTab:'overview',mailId:null,mailFilter:'Inbox',peopleTab:'hiring',settingsTab:'profile',integrationTab:'catalog',aiHistory:[],selected:new Set(),mobile:false};
TF.user=id=>TF.db.users.find(u=>u.id===id)||TF.db.users[0];TF.me=()=>TF.user('u1');TF.project=id=>TF.db.projects.find(p=>p.id===id);TF.task=id=>TF.db.tasks.find(t=>t.id===id);TF.activeOrg=()=>TF.db.session.org;TF.org=()=>TF.db.orgs.find(o=>o.id===TF.activeOrg());TF.today=()=>TF.db.preferences.referenceDate||TF.DEMO_DATE;
TF.isPersonal=t=>TF.project(t.project)?.org==='personal';TF.isTerminal=t=>['Done','Cancelled'].includes(t.status);TF.overdue=t=>!!t.due&&t.due<TF.today()&&!TF.isTerminal(t);TF.visibleProject=p=>p.org==='personal'?p.owner==='u1':p.org===TF.activeOrg();TF.visibleTask=t=>{let p=TF.project(t.project);return p&&TF.visibleProject(p)};
TF.projects=(scope='company')=>TF.db.projects.filter(p=>!p.archived&&TF.visibleProject(p)&&(scope==='all'||scope==='personal'&&p.org==='personal'||scope==='company'&&p.org===TF.activeOrg()));
TF.tasks=(scope='company')=>TF.db.tasks.filter(t=>TF.visibleTask(t)&&!TF.project(t.project)?.archived&&(scope==='all'||scope==='mine'&&t.owner==='u1'||scope==='personal'&&TF.isPersonal(t)||scope==='company'&&!TF.isPersonal(t)));
TF.projectTasks=id=>TF.db.tasks.filter(t=>t.project===id&&TF.visibleTask(t));TF.eligible=ts=>ts.filter(t=>t.status!=='Cancelled');
TF.metrics=ts=>{let e=TF.eligible(ts),done=e.filter(t=>t.status==='Done').length;return {total:e.length,done,open:e.length-done,blocked:e.filter(t=>t.status==='Blocked').length,overdue:e.filter(TF.overdue).length,attention:e.filter(t=>t.status==='Blocked'||TF.overdue(t)).length,rate:e.length?Math.round(done/e.length*100):0,hours:e.filter(t=>!TF.isTerminal(t)).reduce((s,t)=>s+(Number(t.hours)||0),0)}};
TF.progress=p=>TF.metrics(TF.projectTasks(p.id)).rate;TF.health=p=>{let ts=TF.projectTasks(p.id);return ts.some(t=>t.status==='Blocked')?'At risk':ts.some(TF.overdue)?'Needs attention':'On track'};
TF.date=(value,opts={})=>value?new Date(value.length===10?value+'T12:00:00':value).toLocaleDateString('en-GB',{day:'numeric',month:'short',...opts}):'No date';TF.shift=(value,n)=>{let d=new Date(value+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+n);return d.toISOString().slice(0,10)};
TF.windowDates=(n=7,end=TF.today())=>Array.from({length:n},(_,i)=>TF.shift(end,i-n+1));TF.inPeriod=t=>{let period=TF.ui.reportPeriod;if(period==='all')return true;let start=TF.shift(TF.today(),period==='week'?-6:-29);return t.due>=start&&t.due<=TF.today()};
TF.permission=route=>{let r=TF.db.session.role;if(['dashboard','work','calendar','personal'].includes(route))return true;if(route==='people')return r==='HR specialist'||r==='Tenant owner'&&TF.db.preferences.hrScope;if(route==='settings'||route==='integrations'||route==='automations')return ['Tenant owner','Org admin'].includes(r);if(['executive','reports'].includes(route))return !['Member','HR specialist'].includes(r);return r!=='HR specialist';};
TF.canEdit=()=>!['Viewer / auditor','Executive / PMO'].includes(TF.db.session.role);
TF.persist=()=>{try{root.localStorage?.setItem(TF.STORAGE_KEY,JSON.stringify(TF.db));TF.persistence=true;return true}catch(e){TF.persistence=false;TF.toast?.('Browser storage is full or unavailable. Export a backup before closing.','warning');return false}};
TF.log=(text,project=null,org=TF.activeOrg())=>{TF.db.activity.unshift({id:TF.id('a'),org,project,user:'u1',text,date:new Date().toISOString()});if(TF.db.activity.length>200)TF.db.activity.length=200;};
TF.commit=(text,mutate,project=null)=>{let before=TF.clone(TF.db);mutate();TF.log(text,project,project?TF.project(project)?.org:TF.activeOrg());TF.persist();TF.render?.();TF.toast?.(text,'success',()=>{TF.db=before;TF.persist();TF.render?.();TF.toast('Change undone')})};
TF.updateTask=(id,patch)=>{const t=TF.task(id);if(!t||!TF.visibleTask(t)||!TF.canEdit())return false;TF.commit('Updated '+t.title,()=>{Object.assign(t,patch);if(patch.status)t.completedAt=patch.status==='Done'?TF.today():null},t.project);return true};
TF.filteredTasks=(scope='mine')=>{let f=TF.ui.filters[TF.ui.route]||{},q=(f.query||'').toLowerCase();let ts=TF.tasks(scope).filter(t=>(!q||t.title.toLowerCase().includes(q)||TF.project(t.project)?.name.toLowerCase().includes(q))&&(!f.status||f.status==='All statuses'||t.status===f.status||f.status==='Overdue'&&TF.overdue(t))&&(!f.priority||f.priority==='All priorities'||t.priority===f.priority)&&(!f.scope||f.scope==='All workspaces'||f.scope==='Private'&&TF.isPersonal(t)||f.scope==='Company'&&!TF.isPersonal(t))&&(!f.owner||f.owner==='all'||t.owner===f.owner)&&(!f.onlyOpen||!TF.isTerminal(t))&&(!f.attention||TF.overdue(t)||t.status==='Blocked'));if(f.sort==='priority')ts.sort((a,b)=>TF.PRIORITIES.indexOf(a.priority)-TF.PRIORITIES.indexOf(b.priority));else if(f.sort==='title')ts.sort((a,b)=>a.title.localeCompare(b.title));else ts.sort((a,b)=>a.due.localeCompare(b.due));return ts};
TF.backup=()=>JSON.stringify(TF.db,null,2);TF.validateBackup=value=>{if(!value||value.schema!==3)return false;const arrays=['orgs','users','projects','tasks','teams','hiring','candidates','onboarding','learning','mail','rules','runs','notifications','integrations','clients','webhooks','webhookLogs','acknowledged','savedReports','exports','invites','activity'];if(!arrays.every(k=>Array.isArray(value[k])))return false;if(!value.preferences||!value.session||!value.orgs.some(o=>o.id===value.session.org))return false;let ps=new Set(value.projects.map(p=>p.id)),us=new Set(value.users.map(u=>u.id));return value.tasks.every(t=>typeof t.title==='string'&&TF.STATUSES.includes(t.status)&&TF.PRIORITIES.includes(t.priority)&&ps.has(t.project)&&us.has(t.owner)&&Array.isArray(t.checklist)&&Array.isArray(t.comments)&&Array.isArray(t.files))&&value.projects.every(p=>Array.isArray(p.members)&&Array.isArray(p.milestones)&&Array.isArray(p.files));};
if(typeof module!=='undefined')module.exports=TF;
})(typeof window!=='undefined'?window:globalThis);
